"""Stage-2g.1 near-target invisible / near-visible matched supplement.

For each pair:
  * the same episode, goal, position and true distance (5-100 m);
  * four frames (t-3 ... t) generated by three RIGHT turns (15 deg each);
  * near-visible: goal relative angle -25 -> +20 deg, visible in all frames;
  * near-invisible: goal relative angle +20 -> +65 deg, visible at t-3/t-2,
    invisible at t (the target leaves the 90 deg FOV);
  * both variants execute the identical RIGHT x3 action sequence, so the
    history actions alone cannot distinguish them.

Only frozen observable inputs are saved for model use:
current RGB tokens, goal tokens, Goal-Current heatmap, baseline/coherent maps,
the 2,858 current features, and compact 74-d features for the previous three
frames plus actions/time. True distance, visibility, projection and labels are
saved in separate columns and are never model inputs.

No full dataset regeneration, no M0/M1 forward, no checkpoint modification.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import shutil
import sys
import time
from pathlib import Path

import numpy as np
import torch

PROJECT_ROOT = Path(__file__).resolve().parent.parent
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from config import ENV, TRAIN  # noqa: E402
from env import RIGHT, ToyUAVEnv, wrap_angle  # noqa: E402
from token_data import (  # noqa: E402
    _set_pose,
    encode_multiscale_goal_tokens,
    goal_conditioned_spatial_heatmap,
)
from utils import image_to_tensor  # noqa: E402
from visual_grounding_v83 import static_grounding  # noqa: E402
from v83_spatial_stage2.stage2g_features import (  # noqa: E402
    compute_feature_vector,
    feature_names,
)
from v83_spatial_stage2.stage2g_labels import (  # noqa: E402
    target_labels,
    visible_target_pixels,
)
from v83_spatial_stage2.stage2g1_common import (  # noqa: E402
    COMPACT_FEATURE_NAMES,
    COMPACT_DIM,
    HISTORY_FRAMES,
    compact_indices,
)
from v83_spatial_training.eval_closedloop_spatial import (  # noqa: E402
    ARCHIVE,
    load_encoder,
)

BAND_ID = {"short": 0, "medium": 1, "long": 2}
VARIANT_CODE = {"near_visible": 0, "near_invisible": 1}
NEAR_VISIBLE_REL = -25.0
NEAR_INVISIBLE_REL = 20.0
TURN_DEG = 15.0
FRAMES = 4
HISTORY_ACTIONS = np.asarray([RIGHT, RIGHT, RIGHT], dtype=np.int8)


def sha256(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def band_ranges():
    return {
        name: (float(dmin), float(dmax))
        for name, _w, dmin, dmax, _amin, _amax in TRAIN.trajectory_mix
    }


def visibility_sequence(env, position, bearing, start_relative_deg):
    rows = []
    for frame in range(FRAMES):
        relative = start_relative_deg + TURN_DEG * frame
        yaw = wrap_angle(bearing - math.radians(relative))
        _set_pose(env, position, yaw)
        projection = env.goal_projection()
        visible_pixels, target_area, visible_fraction = (
            visible_target_pixels(env)
        )
        if projection is None:
            half_size = px = py = slant = float("nan")
        else:
            px, py, slant, half_size = projection
        visible, localizable = target_labels(visible_pixels, half_size)
        rows.append({
            "relative_deg": float(relative),
            "goal_visible_geom": int(projection is not None),
            "goal_px": float(px),
            "goal_py": float(py),
            "goal_slant_m": float(slant),
            "goal_half_size_px": float(half_size),
            "visible_pixels": int(visible_pixels),
            "target_area_px": int(target_area),
            "visible_fraction": float(visible_fraction),
            "target_visible": int(visible),
            "target_localizable": int(localizable),
        })
    return rows


def sequence_valid(variant, rows):
    if variant == "near_visible":
        return all(row["target_visible"] == 1 for row in rows)
    # near-invisible: recent history is visible, current is not.
    return (
        rows[0]["target_visible"] == 1
        and rows[1]["target_visible"] == 1
        and rows[3]["target_visible"] == 0
        and rows[3]["visible_pixels"] == 0
    )


def encode_frame(env, position, relative_deg, bearing, goal_tokens, encoder,
                 device):
    yaw = wrap_angle(bearing - math.radians(relative_deg))
    _set_pose(env, position, yaw)
    observation = env.render()
    tokens = encoder(image_to_tensor(observation, device))
    goal = goal_tokens.unsqueeze(0).to(device=device, dtype=torch.float32)
    heatmap = goal_conditioned_spatial_heatmap(tokens, goal)
    baseline, coherent = static_grounding(tokens, goal)
    features = compute_feature_vector(
        tokens, goal, heatmap, baseline, coherent
    )
    return {
        "tokens": tokens,
        "goal": goal,
        "heatmap": heatmap,
        "baseline": baseline,
        "coherent": coherent,
        "features": features,
    }


def sample_distance(rng):
    draw = float(rng.random())
    if draw < 0.50:
        return float(rng.uniform(5.0, 40.0))
    if draw < 0.80:
        return float(rng.uniform(40.0, 70.0))
    return float(rng.uniform(70.0, 100.0))


def sample_position(env, distance_m, rng):
    bearing = float(rng.uniform(-math.pi, math.pi))
    unit = np.asarray(
        [math.cos(bearing), math.sin(bearing)], dtype=np.float32
    )
    position = np.asarray(env.goal, dtype=np.float32) - distance_m * unit
    margin = 1.0
    if not (
        margin <= position[0] <= env.world_size - margin
        and margin <= position[1] <= env.world_size - margin
    ):
        return None
    return position, bearing


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--split", choices=["train", "val"], required=True)
    parser.add_argument("--pairs", type=int, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument(
        "--data-root", type=Path,
        default=Path("runs/v83_spatial_stage2/datasets"),
    )
    parser.add_argument("--seed", type=int, default=0)
    parser.add_argument("--attempts-per-pair", type=int, default=40)
    parser.add_argument("--max-pairs", type=int, default=None)
    args = parser.parse_args()
    pairs_target = args.pairs if args.max_pairs is None else min(
        args.pairs, args.max_pairs
    )
    output_dir = Path(args.output_dir)
    if output_dir.exists():
        raise SystemExit(f"Refusing to overwrite {output_dir}")
    output_dir.mkdir(parents=True, exist_ok=False)

    data_dir = args.data_root / (
        "train_600" if args.split == "train" else "dev_val_180"
    )
    stats = json.loads(
        (data_dir / "dataset_stats.json").read_text(encoding="utf-8")
    )
    trajectories = stats["trajectories"]
    ranges = band_ranges()
    encoder_path = ARCHIVE / "shared_encoder.pt"
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    torch.set_grad_enabled(False)
    encoder = load_encoder(device)
    names = feature_names()
    compact_idx = compact_indices(names)

    # Storage estimate: current tokens dominate.
    per_state = (
        576 * 384 * 2  # tokens float16
        + 3 * 384 * 2  # goal tokens
        + 3 * 8 * 8 * 2  # heatmap
        + 2 * 24 * 24 * 2  # baseline + coherent
        + 2858 * 4  # current features
        + HISTORY_FRAMES * COMPACT_DIM * 4  # history features
        + 1024  # labels / overhead margin
    )
    required_bytes = 2 * pairs_target * per_state + 100 * 1024 * 1024
    free_bytes = shutil.disk_usage(PROJECT_ROOT).free
    if free_bytes < required_bytes + 2 * 1024 ** 3:
        raise SystemExit(
            f"Insufficient disk: need {required_bytes/1e9:.2f} GB + 2 GB "
            f"margin, have {free_bytes/1e9:.2f} GB"
        )

    n_states = 2 * pairs_target
    tokens_buf = np.zeros((n_states, 576, 384), dtype=np.float16)
    goals_buf = np.zeros((n_states, 3, 384), dtype=np.float16)
    heatmaps_buf = np.zeros((n_states, 3, 8, 8), dtype=np.float16)
    baseline_buf = np.zeros((n_states, 24, 24), dtype=np.float16)
    coherent_buf = np.zeros((n_states, 24, 24), dtype=np.float16)
    current_buf = np.zeros((n_states, 2858), dtype=np.float32)
    history_buf = np.zeros(
        (n_states, HISTORY_FRAMES, COMPACT_DIM), dtype=np.float32
    )
    history_actions_buf = np.full(
        (n_states, HISTORY_FRAMES), -1, dtype=np.int8
    )
    history_dt_buf = np.zeros((n_states, HISTORY_FRAMES), dtype=np.float32)
    history_step_buf = np.zeros(
        (n_states, HISTORY_FRAMES), dtype=np.int32
    )
    labels = {
        name: np.zeros(n_states, dtype=dtype)
        for name, dtype in {
            "distance_m": np.float32,
            "goal_visible_geom": np.int8,
            "goal_px": np.float32,
            "goal_py": np.float32,
            "goal_slant_m": np.float32,
            "goal_half_size_px": np.float32,
            "visible_pixels": np.int32,
            "target_area_px": np.int32,
            "visible_fraction": np.float32,
            "target_visible": np.int8,
            "target_localizable": np.int8,
            "near_target_invisible": np.int8,
            "pair_id": np.int32,
            "variant": np.int8,
            "episode_id": np.int32,
            "step_id": np.int32,
            "band": np.int8,
            "episode_seed": np.int32,
            "start_relative_deg": np.float32,
            "final_relative_deg": np.float32,
        }.items()
    }

    rng = np.random.default_rng(int(args.seed))
    order = rng.permutation(len(trajectories))
    order_index = 0
    goal_cache = {}
    env = ToyUAVEnv()
    count = 0
    pair_id = 0
    attempts = 0
    failed_pairs = 0
    generated_pairs = 0
    started = time.time()

    def next_episode():
        nonlocal order, order_index
        if order_index >= len(order):
            order = rng.permutation(len(trajectories))
            order_index = 0
        episode = int(order[order_index])
        order_index += 1
        return episode

    while generated_pairs < pairs_target:
        generated = False
        for _attempt in range(int(args.attempts_per_pair)):
            attempts += 1
            episode = next_episode()
            record = trajectories[episode]
            seed = int(record["seed"])
            band = str(record["band"])
            dmin, dmax = ranges[band]
            env.reset(
                seed=seed,
                goal_distance_range_m=(dmin, dmax),
                render_observation=False,
            )
            if episode not in goal_cache:
                goal_cache[episode] = (
                    encode_multiscale_goal_tokens(
                        env.get_goal_reference_multiscale_rgbs(),
                        encoder,
                        device,
                    ).detach().cpu().half()
                )
            goal_tokens = goal_cache[episode].to(
                device=device, dtype=torch.float32
            )
            distance = sample_distance(rng)
            sampled = sample_position(env, distance, rng)
            if sampled is None:
                continue
            position, bearing = sampled

            visible_rows = visibility_sequence(
                env, position, bearing, NEAR_VISIBLE_REL
            )
            invisible_rows = visibility_sequence(
                env, position, bearing, NEAR_INVISIBLE_REL
            )
            if not sequence_valid("near_visible", visible_rows):
                continue
            if not sequence_valid("near_invisible", invisible_rows):
                continue

            sequences = {}
            for variant, start_relative in (
                ("near_visible", NEAR_VISIBLE_REL),
                ("near_invisible", NEAR_INVISIBLE_REL),
            ):
                frames = []
                for frame in range(FRAMES):
                    relative = start_relative + TURN_DEG * frame
                    frames.append(
                        encode_frame(
                            env, position, relative, bearing,
                            goal_tokens, encoder, device,
                        )
                    )
                sequences[variant] = frames

            # Verify encoded final labels against the pre-check.
            for variant, rows in (
                ("near_visible", visible_rows),
                ("near_invisible", invisible_rows),
            ):
                final = rows[3]
                encoded = sequences[variant][3]
                projection = env.goal_projection()
                # Recompute the final label after encoding; the projection is
                # deterministic for the same pose.
                _set_pose(
                    env, position,
                    wrap_angle(
                        bearing - math.radians(
                            (NEAR_VISIBLE_REL if variant == "near_visible"
                             else NEAR_INVISIBLE_REL) + TURN_DEG * 3
                        )
                    ),
                )
                visible_pixels, target_area, visible_fraction = (
                    visible_target_pixels(env)
                )
                half_size = (
                    env.goal_projection()[3]
                    if env.goal_projection() is not None
                    else float("nan")
                )
                visible, localizable = target_labels(
                    visible_pixels, half_size
                )
                if variant == "near_visible":
                    if visible != 1:
                        break
                else:
                    if visible != 0:
                        break
            else:
                # Both final labels are as required; append the two states.
                for variant, start_relative in (
                    ("near_visible", NEAR_VISIBLE_REL),
                    ("near_invisible", NEAR_INVISIBLE_REL),
                ):
                    frames = sequences[variant]
                    current = frames[3]
                    rows = (
                        visible_rows if variant == "near_visible"
                        else invisible_rows
                    )
                    final = rows[3]
                    base_step = 1_000_000 + pair_id * 10 + (
                        0 if variant == "near_visible" else 5
                    )
                    current_step = base_step + 3
                    history = [frames[2], frames[1], frames[0]]
                    tokens_buf[count] = (
                        current["tokens"].squeeze(0).cpu().half().numpy()
                    )
                    goals_buf[count] = goal_tokens.half().cpu().numpy()
                    heatmaps_buf[count] = (
                        current["heatmap"].squeeze(0).cpu().half().numpy()
                    )
                    baseline_buf[count] = (
                        current["baseline"].squeeze(0).cpu().half().numpy()
                    )
                    coherent_buf[count] = (
                        current["coherent"].squeeze(0).cpu().half().numpy()
                    )
                    current_buf[count] = (
                        current["features"].squeeze(0).cpu().numpy()
                    )
                    for frame_index, frame in enumerate(history):
                        history_buf[count, frame_index] = (
                            frame["features"].squeeze(0).cpu().numpy()[
                                compact_idx
                            ]
                        )
                        history_actions_buf[count, frame_index] = RIGHT
                        history_dt_buf[count, frame_index] = 1.0
                        history_step_buf[count, frame_index] = (
                            current_step - 1 - frame_index
                        )
                    labels["distance_m"][count] = float(distance)
                    labels["goal_visible_geom"][count] = int(
                        final["goal_visible_geom"]
                    )
                    labels["goal_px"][count] = float(final["goal_px"])
                    labels["goal_py"][count] = float(final["goal_py"])
                    labels["goal_slant_m"][count] = float(
                        final["goal_slant_m"]
                    )
                    labels["goal_half_size_px"][count] = float(
                        final["goal_half_size_px"]
                    )
                    labels["visible_pixels"][count] = int(
                        final["visible_pixels"]
                    )
                    labels["target_area_px"][count] = int(
                        final["target_area_px"]
                    )
                    labels["visible_fraction"][count] = float(
                        final["visible_fraction"]
                    )
                    labels["target_visible"][count] = int(
                        final["target_visible"]
                    )
                    labels["target_localizable"][count] = int(
                        final["target_localizable"]
                    )
                    labels["near_target_invisible"][count] = int(
                        float(distance) < 100.0
                        and int(final["target_visible"]) == 0
                    )
                    labels["pair_id"][count] = int(pair_id)
                    labels["variant"][count] = int(
                        VARIANT_CODE[variant]
                    )
                    labels["episode_id"][count] = int(episode)
                    labels["step_id"][count] = int(current_step)
                    labels["band"][count] = int(BAND_ID[band])
                    labels["episode_seed"][count] = int(seed)
                    labels["start_relative_deg"][count] = float(
                        start_relative
                    )
                    labels["final_relative_deg"][count] = float(
                        start_relative + TURN_DEG * 3
                    )
                    count += 1
                generated = True
                break
        if generated:
            generated_pairs += 1
            pair_id += 1
            if generated_pairs % 50 == 0:
                print(
                    f"  generated {generated_pairs}/{pairs_target} pairs "
                    f"({count} states, {time.time() - started:.1f}s)",
                    flush=True,
                )
        else:
            failed_pairs += 1
            if failed_pairs <= 5:
                print(
                    f"  warning: pair {pair_id} failed after "
                    f"{args.attempts_per_pair} attempts",
                    flush=True,
                )
            if failed_pairs > max(5, pairs_target // 4):
                raise SystemExit(
                    f"Too many failed pairs ({failed_pairs}); aborting"
                )

    # Trim to generated states.
    n = count
    arrays = {
        "tokens": tokens_buf[:n],
        "goal_tokens": goals_buf[:n],
        "heatmaps": heatmaps_buf[:n],
        "baseline": baseline_buf[:n],
        "coherent": coherent_buf[:n],
        "current_features": current_buf[:n],
        "history_features": history_buf[:n],
        "history_actions": history_actions_buf[:n],
        "history_dt": history_dt_buf[:n],
        "history_step_ids": history_step_buf[:n],
        "feature_names": np.asarray(names),
        "compact_feature_names": np.asarray(COMPACT_FEATURE_NAMES),
        **{name: value[:n] for name, value in labels.items()},
    }
    out_path = output_dir / f"supplement_{args.split}.npz"
    np.savez(out_path, **arrays)
    summary = {
        "split": args.split,
        "pairs_target": pairs_target,
        "pairs_generated": int(generated_pairs),
        "failed_pairs": int(failed_pairs),
        "states": int(n),
        "attempts": int(attempts),
        "near_visible": int((labels["variant"][:n] == 0).sum()),
        "near_invisible": int((labels["variant"][:n] == 1).sum()),
        "near_localizable": int(
            ((labels["variant"][:n] == 0)
             & (labels["target_localizable"][:n] == 1)).sum()
        ),
        "near_target_invisible": int(
            labels["near_target_invisible"][:n].sum()
        ),
        "distance_quantiles": {
            str(q): float(np.quantile(labels["distance_m"][:n], q))
            for q in (0.0, 0.1, 0.25, 0.5, 0.75, 0.9, 1.0)
        },
        "elapsed_s": float(time.time() - started),
        "size_bytes": int(out_path.stat().st_size),
        "encoder": {
            "path": str(encoder_path),
            "sha256": sha256(encoder_path),
        },
        "labels": {
            "target_visible": "occlusion-aware visible_pixels >= 1",
            "target_localizable": (
                "target_visible AND goal_half_size_px >= 10 "
                "AND visible_pixels >= 16"
            ),
            "near_target_invisible": (
                "true distance < 100 m AND target_visible == 0"
            ),
        },
        "history": {
            "frames": HISTORY_FRAMES,
            "actions": "RIGHT x3 (identical for both variants)",
            "order": "t-1, t-2, t-3",
            "compact_dim": COMPACT_DIM,
            "compact_features": list(COMPACT_FEATURE_NAMES),
        },
        "pairing": {
            "same_episode": True,
            "same_position": True,
            "same_distance": True,
            "same_actions": True,
            "difference": "initial yaw / visual history",
            "near_visible_relative_deg": [NEAR_VISIBLE_REL, NEAR_VISIBLE_REL + 45.0],
            "near_invisible_relative_deg": [NEAR_INVISIBLE_REL, NEAR_INVISIBLE_REL + 45.0],
        },
    }
    (output_dir / f"supplement_{args.split}_summary.json").write_text(
        json.dumps(summary, indent=2), encoding="utf-8"
    )
    print(json.dumps({
        "split": args.split,
        "pairs_generated": summary["pairs_generated"],
        "states": summary["states"],
        "near_localizable": summary["near_localizable"],
        "near_invisible": summary["near_invisible"],
        "elapsed_s": round(summary["elapsed_s"], 1),
        "size_gb": round(summary["size_bytes"] / 1e9, 3),
        "output": str(out_path),
    }, indent=2), flush=True)


if __name__ == "__main__":
    main()
